import sys
import json
import argparse
import time
import random
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)


def load_text_from_file(path: str) -> str:
    with open(path, "r", encoding="utf-8") as f:
        return f.read()


def load_text_from_url(url: str, timeout: float = 10.0, retries: int = 3, backoff: float = 0.5) -> str:
    attempt = 0
    last_err = None
    while attempt < retries:
        try:
            req = Request(url, headers={"User-Agent": "social-sim/1.0"})
            with urlopen(req, timeout=timeout) as resp:
                return resp.read().decode("utf-8")
        except (HTTPError, URLError, TimeoutError) as e:
            last_err = e
            time.sleep(backoff * (2 ** attempt))
            attempt += 1
    raise RuntimeError(f"Failed to fetch URL after {retries} attempts: {last_err}")


def parse_json(text: str):
    try:
        return json.loads(text)
    except json.JSONDecodeError as e:
        lines = text.splitlines()
        start = max(0, e.lineno - 2)
        end = min(len(lines), e.lineno + 1)
        eprint(f"JSON parse error at line {e.lineno}, column {e.colno}: {e.msg}")
        for i in range(start, end):
            prefix = ">>" if (i + 1) == e.lineno else "  "
            eprint(f"{prefix} {i + 1}: {lines[i]}")
        sys.exit(1)


def validate_input(data) -> None:
    if not isinstance(data, dict):
        eprint("Input JSON must be an object at top level.")
        sys.exit(1)
    required = {"agents": list, "steps": int}
    for k, t in required.items():
        if k not in data:
            eprint(f"Missing required key: '{k}'")
            sys.exit(1)
        if not isinstance(data[k], t):
            eprint(f"Key '{k}' must be of type {t.__name__}")
            sys.exit(1)
    if "interactions" in data and not isinstance(data["interactions"], list):
        eprint("Optional key 'interactions' must be a list if present.")
        sys.exit(1)


def run_simulation(data, seed=None) -> dict:
    if seed is not None:
        random.seed(seed)
    agents = data["agents"]
    steps = data["steps"]
    interactions = 0
    for _ in range(steps):
        if len(agents) >= 2:
            a = random.randrange(len(agents))
            b = random.randrange(len(agents) - 1)
            if b >= a:
                b += 1
            interactions += 1
    return {
        "num_agents": len(agents),
        "steps": steps,
        "interactions": interactions,
        "status": "ok"
    }


def main():
    parser = argparse.ArgumentParser(description="Social simulation runner")
    parser.add_argument("--file", help="Path to JSON input file")
    parser.add_argument("--url", help="URL to JSON input")
    parser.add_argument("--seed", type=int, default=None, help="Random seed for reproducibility")
    parser.add_argument("--timeout", type=float, default=10.0, help="Network timeout in seconds")
    parser.add_argument("--retries", type=int, default=3, help="Network retries for URL inputs")
    args = parser.parse_args()

    if bool(args.file) == bool(args.url):
        eprint("Provide exactly one of --file or --url")
        sys.exit(1)

    try:
        if args.file:
            text = load_text_from_file(args.file)
        else:
            text = load_text_from_url(args.url, timeout=args.timeout, retries=args.retries)
    except Exception as e:
        eprint(f"Failed to load input: {e}")
        sys.exit(1)

    data = parse_json(text)
    validate_input(data)
    result = run_simulation(data, seed=args.seed)
    print(json.dumps(result))
    sys.exit(0)

# Execute main for both direct execution and sandbox wrapper invocation
main()

